const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Namibia geometry
  var namibia = ee.FeatureCollection('FAO/GAUL/2015/level0')
                  .filter(ee.Filter.eq('ADM0_NAME', 'Namibia'));

  // Define date range for January 2021
  var startDate = '2021-01-01';
  var endDate = '2021-01-31';

  // Load CHIRPS precipitation data
  var chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
                .filterBounds(namibia)
                .filterDate(startDate, endDate);

  // Check collection size
  var count = chirps.size().getInfo();
  console.log('January 2021 images: ' + count);

  if (count === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // Sum precipitation for the month (in mm)
  var totalPrecip = chirps.sum();

  // Convert mm to inches (1 inch = 25.4 mm)
  var totalPrecipInches = totalPrecip.divide(25.4);

  // Calculate mean precipitation over Namibia
  var stats = totalPrecipInches.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: namibia,
    scale: 5000,
    maxPixels: 1e9
  });

  var meanInches = stats.get('precipitation').getInfo();
  var pixelCount = stats.get('precipitation_count').getInfo();

  console.log('Mean rainfall (inches): ' + meanInches?.toFixed(2));
  console.log('Valid pixels: ' + pixelCount);

  // Validation checks
  if (pixelCount === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  if (meanInches === null || meanInches === undefined || isNaN(meanInches)) {
    console.log('<answer>C3</answer>');
    return;
  }

  // Check if > 7 inches
  if (meanInches > 7) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
